   532→// parseStructDecl - 구조체 선언 파싱
   533→func (p *Parser) parseStructDecl() ast.Stmt {
   534→	isMutable := false
   535→	var structToken lexer.Token
   536→
   537→	if p.match(lexer.TokenKeywordMutable) {
   538→		isMutable = true
   539→	}
   540→
   541→	structToken = p.current
   542→	p.expect(lexer.TokenKeywordStruct)
   543→
   544→	if p.current.Type != lexer.TokenIdentifier {
   545→		p.error("구조체 이름이 필요합니다")
   546→		return nil
   547→	}
   548→	name := p.current.Lexeme
   549→	p.advance()
   550→
   551→	// 필드 파싱
   552→	fields := []*ast.StructField{}
   553→	for p.current.Type != lexer.TokenKeywordEnd {
   554→		if p.match(lexer.TokenNewline) {
   555→			continue
   556→		}
   557→
   558→		if p.current.Type != lexer.TokenIdentifier {
   559→			p.error("필드 이름이 필요합니다")
   560→			return nil
   561→		}
   562→		fieldName := p.current.Lexeme
   563→		p.advance()
   564→
   565→		var fieldType string
   566→		if p.match(lexer.TokenDoubleColon) {
   567→			if p.current.Type != lexer.TokenIdentifier {
   568→				p.error("필드 타입이 필요합니다")
   569→				return nil
   570→			}
   571→			fieldType = p.current.Lexeme
   572→			p.advance()
   573→		}
   574→
   575→		fields = append(fields, &ast.StructField{
   576→			Name: fieldName,
   577→			Type: fieldType,
   578→		})
   579→	}
   580→
   581→	p.expect(lexer.TokenKeywordEnd)
   582→
   583→	return &ast.StructDecl{
   584→		Name:      name,
   585→		IsMutable: isMutable,
   586→		Fields:    fields,
   587→		Struct:    structToken,
   588→	}
   589→}
