   591→// parseIfStmt - if 문 파싱
   592→func (p *Parser) parseIfStmt() ast.Stmt {
   593→	ifToken := p.current
   594→	p.advance()
   595→
   596→	condition := p.parseExpression()
   597→	if condition == nil {
   598→		p.error("if 조건이 필요합니다")
   599→		return nil
   600→	}
   601→
   602→	thenBody := p.parseBlock(lexer.TokenKeywordElseif, lexer.TokenKeywordElse, lexer.TokenKeywordEnd)
   603→
   604→	elseIfs := []*ast.ElseIfClause{}
   605→	for p.match(lexer.TokenKeywordElseif) {
   606→		elifToken := p.tokens[p.pos-1]
   607→		elifCond := p.parseExpression()
   608→		if elifCond == nil {
   609→			p.error("elseif 조건이 필요합니다")
   610→			return nil
   611→		}
   612→		elifBody := p.parseBlock(lexer.TokenKeywordElseif, lexer.TokenKeywordElse, lexer.TokenKeywordEnd)
   613→		elseIfs = append(elseIfs, &ast.ElseIfClause{
   614→			Condition: elifCond,
   615→			Body:      elifBody,
   616→			ElseIf:    elifToken,
   617→		})
   618→	}
   619→
   620→	var elseBody []ast.Stmt
   621→	if p.match(lexer.TokenKeywordElse) {
   622→		elseBody = p.parseBlock(lexer.TokenKeywordEnd)
   623→	}
   624→
   625→	p.expect(lexer.TokenKeywordEnd)
   626→
   627→	return &ast.IfStmt{
   628→		Condition: condition,
   629→		Then:      thenBody,
   630→		ElseIfs:   elseIfs,
   631→		Else:      elseBody,
   632→		If:        ifToken,
   633→	}
   634→}
