   636→// parseWhileStmt - while 루프 파싱
   637→func (p *Parser) parseWhileStmt() ast.Stmt {
   638→	whileToken := p.current
   639→	p.advance()
   640→
   641→	condition := p.parseExpression()
   642→	if condition == nil {
   643→		p.error("while 조건이 필요합니다")
   644→		return nil
   645→	}
   646→
   647→	body := p.parseBlock(lexer.TokenKeywordEnd)
   648→	p.expect(lexer.TokenKeywordEnd)
   649→
   650→	return &ast.WhileStmt{
   651→		Condition: condition,
   652→		Body:      body,
   653→		While:     whileToken,
   654→	}
   655→}
