     8→// Lexer - Julia 렉서
     9→type Lexer struct {
    10→	input  string
    11→	pos    int  // 현재 위치
    12→	line   int  // 현재 줄
    13→	column int  // 현재 열
    14→	offset int  // 바이트 오프셋
    15→	ch     rune // 현재 문자
    16→	file   string
    17→}
    18→
    19→// NewLexer - 새로운 Lexer 생성
    20→func NewLexer(input string) *Lexer {
    21→	l := &Lexer{
    22→		input:  input,
    23→		pos:    0,
    24→		line:   1,
    25→		column: 0,
    26→		offset: 0,
    27→		ch:     rune(0),
    28→		file:   "<stdin>",
    29→	}
    30→	l.readChar()
    31→	return l
    32→}
    33→
    34→// NewLexerWithFile - 파일명을 포함한 Lexer 생성
    35→func NewLexerWithFile(input, filename string) *Lexer {
    36→	l := NewLexer(input)
    37→	l.file = filename
    38→	return l
    39→}
    40→
    41→// readChar - 다음 문자 읽기
    42→func (l *Lexer) readChar() {
    43→	if l.pos >= len(l.input) {
    44→		l.ch = rune(0)
    45→	} else {
    46→		l.ch = rune(l.input[l.pos])
    47→	}
    48→	l.pos++
    49→	l.offset++
    50→	l.column++
    51→}
    52→
    53→// peekChar - 다음 문자 미리보기 (읽지 않음)
    54→func (l *Lexer) peekChar() rune {
    55→	if l.pos >= len(l.input) {
    56→		return rune(0)
    57→	}
    58→	return rune(l.input[l.pos])
    59→}
    60→
    61→// peekCharN - n번째 앞의 문자 보기
    62→func (l *Lexer) peekCharN(n int) rune {
